// The focus when a panel window closes, in Chromium, on the pages generated by the panel (r9: focus inside on opening,
// kept, given back on closing, Escape closes). Found walking every function of the 0.9.0 panel on a clean server
// (18/11/2026): a window of the panel opened over another one ("Go ahead?" before revealing a password, the fresh
// confirmation) left the focus on the body when it closed; the window below no longer heard Escape, and a keyboard or
// screen reader user was left outside, behind it. The fix is in the shared panel-reboot.js, for every window.
//
//  1. Mailboxes, the client configuration of a mailbox: the focus goes inside, Escape closes it, the focus comes back to
//     the button that opened it.
//  2. Opened again, "Reveal" asks "Go ahead?"; cancelled with Escape: the focus is back inside the client configuration,
//     on "Reveal"; Tab stays inside it; Escape closes it.
//  3. Opened again, "Reveal", "Yes, go ahead": the password arrives (the page disables "Reveal" while it works), the
//     focus is inside the client configuration (on the window itself), and Escape closes it.
//
// The server is simulated (the mailbox list, its usage, the password). Usage (from the project root, with the pages of
// PageGenerator in $D, see csp-browser-test.js):
//   NODE_PATH=$(npm root -g) node tests/dialog-focus-browser-test.js $D
const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');
const csp = require('./browser-csp');

const pages = process.argv[2];
const resources = path.join(__dirname, '..', 'src', 'main', 'resources');
const BASE = 'http://panel.test';
const BOX = { id: 7, email: 'info@example.test', name: 'Info', domain: 'example.test', quota_mb: 1024, active: true,
    receive_enabled: true, last_login: '2026-11-18 10:00:00', autoresponder_enabled: false, forwarding_count: 0, filters_count: 0 };
let failures = 0;
const check = (what, ok) => { console.log((ok ? '  OK     ' : '  FAILED ') + what); if (!ok) failures++; };
const json = (route, body) => route.fulfill({ status: 200, contentType: 'application/json', body: JSON.stringify(body) });

async function serve(route) {
    const p = new URL(route.request().url()).pathname;
    if (p === '/mailboxes') {
        const html = fs.readFileSync(path.join(pages, 'mailboxes.en.html'), 'utf8').replace(/\{\{CSRF_TOKEN\}\}/g, 'csrf-test')
            .replace(/\{\{THEME\}\}/g, 'light').replace(/\{\{COLOR_SCHEME\}\}/g, 'light');
        return route.fulfill({ status: 200, contentType: 'text/html; charset=utf-8', body: html, headers: csp.headers(pages) });
    }
    if (p.startsWith('/assets/')) return csp.asset(route, pages, p);
    if (p.startsWith('/i18n/')) return route.fulfill({ status: 200, contentType: 'application/javascript', body: fs.readFileSync(path.join(pages, p)) });
    if (p.startsWith('/vendor/') || p.startsWith('/fa/')) {
        const f = path.join(resources, p);
        if (!fs.existsSync(f)) return route.fulfill({ status: 404, body: '' });
        const type = p.endsWith('.css') ? 'text/css' : p.endsWith('.js') ? 'application/javascript' : p.endsWith('.woff2') ? 'font/woff2' : 'application/octet-stream';
        return route.fulfill({ status: 200, contentType: type, body: fs.readFileSync(f) });
    }
    if (p === '/api/mailboxes') return json(route, { success: true, mailboxes: [BOX] });
    if (p === '/api/mailbox-quota') return json(route, { success: true, applied: true, mailboxes: [{ email: BOX.email, used_kb: 100, limit_kb: 0, percent: 0 }] });
    if (p === '/api/mailbox-password') { await new Promise(r => setTimeout(r, 400)); return json(route, { success: true, password: 'Simulated-Password-9' }); }
    if (p === '/api/domains') return json(route, { success: true, domains: [{ id: 1, domain: BOX.domain }] });
    return json(route, { success: false, error: 'not simulated' });
}

(async () => {
    const browser = await chromium.launch({ executablePath: process.env.CHROMIUM || '/opt/pw-browsers/chromium' }).catch(() => chromium.launch());
    const ctx = await browser.newContext({ viewport: { width: 1280, height: 900 }, locale: 'en-GB' });
    await ctx.route('**/*', serve);
    const page = await ctx.newPage();
    const errors = [];
    page.on('pageerror', e => errors.push(e.message));
    csp.watch(page, errors);

    const where = () => page.evaluate(() => {
        const a = document.activeElement, m = a && a.closest('.modal');
        return { tag: a ? a.tagName : '', id: a ? a.id : '', click: a && a.dataset ? (a.dataset.onClick || '') : '', modal: m ? m.id : '' };
    });
    // Fully open: Bootstrap moves the focus in at the end of its fade (shown.bs.modal).
    const shown = id => page.evaluate(i => new Promise(r => {
        const m = document.getElementById(i);
        m.addEventListener('shown.bs.modal', () => setTimeout(r, 50), { once: true });
    }), id);
    // Fully closed: hidden.bs.modal comes after the backdrop's fade, and that is when the focus is given back.
    const closing = id => page.evaluate(i => { window.__closed = window.__closed || {}; window.__closed[i] = false;
        document.getElementById(i).addEventListener('hidden.bs.modal', () => setTimeout(() => { window.__closed[i] = true; }, 50), { once: true }); }, id);
    const gone = id => page.waitForFunction(i => window.__closed && window.__closed[i] === true, id, { timeout: 5000 });
    const openConfig = async () => {
        const opened = shown('mailConfigModal');
        await page.click('tr:has-text("' + BOX.email + '") [data-on-click^="showMailConfig("]');
        await opened;
    };

    try {
        await page.goto(BASE + '/mailboxes');
        await page.waitForSelector('tr:has-text("' + BOX.email + '") [data-on-click^="showMailConfig("]');

        console.log('== 1. The client configuration alone ==');
        await openConfig();
        check('the focus goes inside it', (await where()).modal === 'mailConfigModal');
        await closing('mailConfigModal');
        await page.keyboard.press('Escape');
        await gone('mailConfigModal');
        const back = await where();
        check('Escape closes it, and the focus is back on the button that opened it (' + back.click.slice(0, 30) + ')', back.click.startsWith('showMailConfig('));

        console.log('\n== 2. "Reveal", "Go ahead?" cancelled ==');
        await openConfig();
        const asked = shown('panelAskModal');
        await page.click('#mailConfigModal [data-on-click^="revealCfgPassword("]');
        await asked;
        const onAsk = await where();
        check('"Go ahead?" has the focus (' + (onAsk.modal || 'none') + ' ' + (onAsk.id || onAsk.tag) + ')', onAsk.modal === 'panelAskModal');
        await closing('panelAskModal');
        await page.keyboard.press('Escape');
        await gone('panelAskModal');
        const after = await where();
        check('cancelled: the focus is back inside the client configuration, on "Reveal" (' + after.modal + ' ' + after.click.slice(0, 20) + ')',
            after.modal === 'mailConfigModal' && after.click.startsWith('revealCfgPassword('));
        let inside = true;
        for (let i = 0; i < 12; i++) { await page.keyboard.press('Tab'); if ((await where()).modal !== 'mailConfigModal') inside = false; }
        check('Tab stays inside it', inside);
        await closing('mailConfigModal');
        await page.keyboard.press('Escape');
        await gone('mailConfigModal');
        check('and Escape closes it', await page.locator('#mailConfigModal.show').count() === 0);

        console.log('\n== 3. "Reveal", "Yes, go ahead" ==');
        await openConfig();
        const asked2 = shown('panelAskModal');
        await page.click('#mailConfigModal [data-on-click^="revealCfgPassword("]');
        await asked2;
        await closing('panelAskModal');
        await page.click('#panelAskGo');
        await gone('panelAskModal');
        await page.waitForFunction(() => document.getElementById('cfgPasswordField').value === 'Simulated-Password-9', null, { timeout: 5000 });
        const after2 = await where();
        check('the password arrives and the focus is inside the client configuration (' + (after2.id || after2.tag) + ')', after2.modal === 'mailConfigModal');
        await closing('mailConfigModal');
        await page.keyboard.press('Escape');
        await gone('mailConfigModal');
        check('Escape closes it', await page.locator('#mailConfigModal.show').count() === 0);
    } catch (e) {
        check('the test went to the end (' + e.message.split('\n')[0] + ')', false);
    } finally {
        check('no page error, no policy violation' + (errors.length ? ': ' + errors.join(' | ') : ''), errors.length === 0);
        await browser.close();
    }
    console.log(failures ? '\n' + failures + ' CHECKS FAILED' : '\nALL OK');
    process.exit(failures ? 1 : 0);
})();
